package com.internship.eligibility.service;
import com.internship.eligibility.dto.ApplicationDto.*; import com.internship.eligibility.entity.*; import com.internship.eligibility.exception.ApiException; import com.internship.eligibility.repository.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import java.util.*;
@Service public class ApplicationService {private final ApplicationRepository apps;private final StudentService students;private final InternshipService internships;public ApplicationService(ApplicationRepository a,StudentService s,InternshipService i){apps=a;students=s;internships=i;}
 public Application create(String email,CreateRequest r){Student s=students.get(email);Internship i=internships.one(r.internshipId());if(apps.existsByStudentAndInternship(s,i))throw new ApiException("You have already applied for this internship",HttpStatus.CONFLICT);var e=internships.check(email,i.getId());if(!e.eligible())throw new ApiException("You are not eligible to apply for this internship",HttpStatus.FORBIDDEN);Application a=new Application();a.setStudent(s);a.setInternship(i);return apps.save(a);}
 public List<Application> mine(String email){return apps.findByStudentOrderByAppliedAtDesc(students.get(email));}public List<Application> all(){return apps.findAllByOrderByAppliedAtDesc();}public Application status(Long id,StatusRequest r){Application a=apps.findById(id).orElseThrow(()->new ApiException("Application not found",HttpStatus.NOT_FOUND));a.setStatus(r.status());return apps.save(a);}}
